{"script":"
const text = document.body.innerText;
// search for "pairing" and "charging" and Apple Pencil types
const lines = text.split('\n');
const out = [];
for (let i=0;i<lines.length;i++){
  const l = lines[i].toLowerCase();
  if (l.includes('pencil') || l.includes('pair') || l.includes('charg') || l.includes('wireless')) {
    out.push(i + ': ' + lines[i]);
  }
}
return out.join('\n');"}

